<?php
/**
 * Plugin Name: KTD Dashboard Installer
 * Description: Installs the KTD Dashboard Home page template into your active theme and creates the Dashboard page.
 * Version: 1.0
 * Author: KTD
 */

if ( ! defined( 'ABSPATH' ) ) exit;

register_activation_hook( __FILE__, 'ktd_installer_activate' );

function ktd_installer_activate() {
    // 1. Write the template file into the active theme
    $theme_dir     = get_stylesheet_directory();
    $template_file = $theme_dir . '/template-ktd-dashboard.php';
    $b64           = ktd_get_template_b64();
    $decoded       = base64_decode( $b64 );

    if ( $decoded === false ) {
        wp_die( 'KTD Installer: Failed to decode template. Please contact support.' );
    }

    $result = file_put_contents( $template_file, $decoded );
    if ( $result === false ) {
        wp_die( 'KTD Installer: Could not write template file to ' . esc_html( $template_file ) . '. Check folder permissions.' );
    }

    // 2. Create the Dashboard page if it doesn't already exist
    $existing = get_posts( [
        'post_type'      => 'page',
        'post_status'    => 'publish',
        'posts_per_page' => 1,
        'meta_key'       => '_wp_page_template',
        'meta_value'     => 'template-ktd-dashboard.php',
    ] );

    if ( empty( $existing ) ) {
        $page_id = wp_insert_post( [
            'post_title'   => 'Dashboard',
            'post_name'    => 'ktd-dashboard',
            'post_status'  => 'publish',
            'post_type'    => 'page',
            'post_content' => '',
        ] );

        if ( $page_id && ! is_wp_error( $page_id ) ) {
            update_post_meta( $page_id, '_wp_page_template', 'template-ktd-dashboard.php' );
            update_option( 'ktd_dashboard_page_id', $page_id );
        }
    } else {
        update_option( 'ktd_dashboard_page_id', $existing[0]->ID );
    }
}

// Admin notice after activation
add_action( 'admin_notices', 'ktd_installer_notice' );
function ktd_installer_notice() {
    $page_id = get_option( 'ktd_dashboard_page_id' );
    if ( ! $page_id ) return;
    $url = get_permalink( $page_id );
    echo '<div class="notice notice-success is-dismissible"><p>';
    echo '<strong>KTD Dashboard installed!</strong> ';
    echo 'Your dashboard page is ready: <a href="' . esc_url( $url ) . '" target="_blank">' . esc_html( $url ) . '</a>';
    echo '</p></div>';
}

function ktd_get_template_b64() {
    return '';
}
